ci = lambda t: f"{t[0]:.3f} [{t[1]:.3f}, {t[2]:.3f}]"
pm = lambda m, s: f"{m:.3f} +- {s:.3f}"


def cp(k, n, level=0.95):
    lo = 0.0 if k == 0 else beta.ppf((1 - level) / 2, k, n - k + 1)
    hi = 1.0 if k == n else beta.ppf(1 - (1 - level) / 2, k + 1, n - k)
    return lo, hi


L = []
w = L.append
w("# Phase 2: group-aware splits, honest retraining, and conformal recall control")
