data = {t: sd.load_task(t) for t in sd.TASKS}
for t, d in data.items():
    sp_ = groups.loc[d.index, "split"].values
    stc = {s: int(d["stable"].values[sp_ == s].sum()) for s in ("train", "cal", "test")}; n = {s: int((sp_ == s).sum()) for s in ("train", "cal", "test")}
    w(f"| {t} | {len(d):,} | {n['train']:,} | {n['cal']:,} | {n['test']:,} | " + " / ".join(f"{stc[s]} ({pc(stc[s] / n[s])})" for s in ("train", "cal", "test")) + " |")
w("")
